mapper.select:
SELECT 
FROM shift_version version
WHERE version.shift_version_id = #{versionId}

SELECT 
FROM shift_version version
WHERE version.shift_version_id = #{versionId}
  AND version.created_at <= #{knowledgeAsOf}

SELECT 
FROM shift_version version
WHERE version.shift_template_id = #{shiftId}
ORDER BY version.version_number DESC, version.shift_version_id
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM shift_version version
WHERE version.shift_template_id = #{shiftId}

SELECT COALESCE(MAX(version_number), 0) + 1
FROM shift_version
WHERE shift_template_id = #{shiftId}

SELECT COALESCE(MAX(event_sequence), 0) + 1
FROM shift_publication_timeline
WHERE shift_template_id = #{shiftId}

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM shift_publication_timeline published
    WHERE published.shift_template_id = #{shiftId}
      AND published.state = 'PUBLISHED'
      AND published.shift_version_id <> #{excludeVersionId}
      AND (
            #{to} IS NULL
            OR published.business_effective_from < #{to}
      )
      AND COALESCE(
            (
                SELECT MIN(next_fact.business_effective_from)
                FROM shift_publication_timeline next_fact
                WHERE next_fact.shift_template_id =
                        published.shift_template_id
                  AND next_fact.business_effective_from
                        > published.business_effective_from
            ),
            CAST('9999-12-31' AS DATE)
      ) > #{from}
) THEN TRUE ELSE FALSE END

SELECT 
FROM shift_version version
JOIN shift_publication_timeline resolved_fact
  ON resolved_fact.shift_version_id = version.shift_version_id
WHERE resolved_fact.shift_template_id = #{shiftId}
  AND resolved_fact.business_effective_from <= #{date}
  AND resolved_fact.recorded_at <= #{knowledgeAsOf}
  AND resolved_fact.state = 'PUBLISHED'
  AND NOT EXISTS (
      SELECT 1
      FROM shift_publication_timeline newer
      WHERE newer.shift_template_id = resolved_fact.shift_template_id
        AND newer.business_effective_from <= #{date}
        AND newer.recorded_at <= #{knowledgeAsOf}
        AND (
            newer.business_effective_from
                > resolved_fact.business_effective_from
            OR (
                newer.business_effective_from =
                    resolved_fact.business_effective_from
                AND newer.event_sequence > resolved_fact.event_sequence
            )
        )
  )
ORDER BY version.version_number, version.shift_version_id

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM work_calendar_day calendar_day
    WHERE calendar_day.shift_version_override_id = #{versionId}
      AND calendar_day.business_date >= #{businessEffectiveFrom}
) THEN TRUE ELSE FALSE END
